---------------------------- MODULE SetSndRcv_NoFullDrop_13 ----------------------------
EXTENDS FiniteSets

CONSTANT Message

VARIABLES channel, sent

(*--algorithm SimpleChannel
variables channel = {}, sent = {};
begin
  while TRUE do
    either
      (* Send a message *)
      with m \in Message do
        channel := channel \cup {m};
        sent    := sent    \cup {m}
      end with;
    or
      (* Receive a message, only if one is present *)
      with m \in channel do
        channel := channel \ {m}
      end with;
    end either;
  end while;
end algorithm; *)

Init ==
    /\ channel = {}
    /\ sent    = {}

Send ==
    /\ \E m \in Message :
        /\ channel' = channel \cup {m}
        /\ sent'    = sent    \cup {m}
    /\ UNCHANGED << >>

Receive ==
    /\ \E m \in channel :
        /\ channel' = channel \ {m}
        /\ sent'    = sent
    /\ UNCHANGED << >>

Next == Send \/ Receive

(* Type correctness: both variables stay inside the message universe *)
TypeOK ==
    /\ channel \subseteq Message
    /\ sent    \subseteq Message

(* Safety invariant: a value can be in the channel only if it has been sent before *)
SafeChannel ==
    /\ channel \subseteq sent
    /\ TypeOK

Spec == Init /\ [][Next]_<<channel, sent>>

